"""Metadata processing for report-ledger."""

import json
import re
from datetime import date

_DAY_RE = re.compile(r"\d{4}-\d{2}-\d{2}\Z")


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"malformed JSON: {exc}") from exc

    if not isinstance(rows, list):
        raise ValueError("input must be a JSON array of rows")

    total_cents = 0
    earliest = None
    latest = None

    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise ValueError(f"row {index}: expected a JSON object")

        tenant = row.get("tenant")
        if not isinstance(tenant, str) or tenant == "":
            raise ValueError(f"row {index}: tenant must be a nonempty string")

        amount = row.get("amount_cents")
        # bool is a subclass of int; booleans are explicitly invalid.
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError(f"row {index}: amount_cents must be an integer")

        day = row.get("day")
        if not isinstance(day, str) or not _DAY_RE.match(day):
            raise ValueError(f"row {index}: day must be a YYYY-MM-DD string")
        try:
            parsed_day = date.fromisoformat(day)
        except ValueError as exc:
            raise ValueError(f"row {index}: {day!r} is not a valid calendar day") from exc

        total_cents += amount
        if earliest is None or parsed_day < earliest[0]:
            earliest = (parsed_day, day)
        if latest is None or parsed_day > latest[0]:
            latest = (parsed_day, day)

    return {
        "row_count": len(rows),
        "total_cents": total_cents,
        "first_day": earliest[1] if earliest else None,
        "last_day": latest[1] if latest else None,
    }

